"""#653: `horse_runs.csv` を外した版の結果から、report.md の §7 の本文(表を含む)を作る。数字を手で写さないため。
使い方: PYTHONDONTWRITEBYTECODE=1 python3 -I report_nohr_section.py <元の版の出力ディレクトリ> <外した版の出力ディレクトリ> <出力.md>
各ディレクトリには hyp.json・ls20.json・horses.ndjson.gz が要る(build.ts と hypotheses.py・longshots.py の出力)。
"""
import json,gzip
def load(p): return [json.loads(l) for l in gzip.open(p,'rt')]
import sys
orig,nohr,out=sys.argv[1:4]
a=json.load(open(orig+'/hyp.json'));b=json.load(open(nohr+'/hyp.json'))
A=load(orig+'/horses.ndjson.gz');B=load(nohr+'/horses.ndjson.gz')
o=[]
P=o.append
P("\n## 7. `horse_runs.csv` を外した版(2026-11-07 に追加。元の版の 1〜6 節はそのまま)\n")
P("**なぜ作ったか。** `horse_runs.csv` にある馬は「本番が 2026 年に分析した馬」(2,213 頭)なので、2024-08 より前の走が付いていること自体が「2026 年まで走り続けた」印になる(生き残りの偏り。別の探索 `market-blindspots-653-fable` の plan.md §10 が見つけた。そちらは同じ偏りを外した戦績で探索し直し、前半の |z| 上位の 11 件が後半で 1 件も残らず、残った 5 件は 4 件が「買いすぎ」の向きという結論だった。ここでは数値の突き合わせはしていない)。元の版は hist に無い 9,041 走を足していた。この節は、`build.ts` の第 2 引数を `-` にして、**hist の全レースから作った走だけ**で戦績を作り直し、条件の定義・閾値・手順(plan.md)を変えずに流し直した結果。\n")
P("- 手順: `pnpm tsx scripts/market-blindspots-653/build.ts <hist> - <extras> <出力>` →  `hypotheses.py` → `races.py` → `longshots.py`(20 倍)→ `report_tables.py`。")
P("- 元の版の再現を先に確かめた: 元の引数で作り直した `horses.ndjson.gz`・`races.ndjson.gz`・`races.json`・`ls20.json` は元の出力とバイト単位で一致、`hyp.json` は浮動小数点の末尾(約 1e-13 の相対差)だけが違った。木と XGBoost の乱数は固定(`random_state=0`・`seed=0`)。")
P("- テスト: 今回足した `horse-runs.ts`(`horse_runs.csv` の読み込みと、`-` で読まない指定)は、テストを先に書き、モジュールが無い状態の失敗(Red)を実行で確かめてから実装し、通ること(Green、3 件)を確かめた。集計・木・XGBoost の Python にテストがないのは元のまま。")
P("- 後半は計画どおり、前半で通ったものだけ見た。**ただし、元の版の前半を見たあとで材料を変えて流し直しているので、これは事前登録の 1 回目の判定ではなく、2 回目の判定**(通る条件が増えた方向の変化には、その分の割引が要る)。\n")
P("### 7.1 前走が見つかった馬の割合(前走の有無は daysSince が付いたかで数えた)\n")
def pr(R,h,key):
    S=[r for r in R if r['half']==h]; return 100*sum(r[key] is not None for r in S)/len(S)
P("| | 元の版 前半 | 外した版 前半 | 元の版 後半 | 外した版 後半 |\n|---|---:|---:|---:|---:|")
P("| 前走が見つかった馬 | %.1f%% | %.1f%% | %.1f%% | %.1f%% |"%(pr(A,'1','daysSince'),pr(B,'1','daysSince'),pr(A,'2','daysSince'),pr(B,'2','daysSince')))
P("| 過去脚質が作れた馬 | %.1f%% | %.1f%% | %.1f%% | %.1f%% |\n"%(pr(A,'1','style'),pr(B,'1','style'),pr(A,'2','style'),pr(B,'2','style')))
P("### 7.2 前半の月ごとの、前走が見つかった割合と、前走を使う条件の件数(元の版 / 外した版)\n")
P("I1 は「休み明け」(前走から 120 日以上)、K6 は「芝からダート」、P4 は「前走の勝ち馬とのタイム差 2.0 秒以上」(定義は plan.md)。**I1 は 2024-08〜11 で外した版が 0 件**。記録の始まり(2024-08-10)から 120 日後は 2024-12-08 なので、それより前のレースでは、hist の走だけでは 120 日以上空いた前走を作れず、構成上 0 件になる(元の版の 17〜39 件は `horse_runs.csv` の走から来ていた)。\n")
P("| 月 | 馬 | 前走あり | I1 | K6 | P4 |\n|---|---:|---:|---:|---:|---:|")
months=sorted({r['date'][:7] for r in A if r['half']=='1'})
for m in months:
    x=[r for r in A if r['date'][:7]==m]; y=[r for r in B if r['date'][:7]==m]
    f=lambda S:100*sum(r['daysSince'] is not None for r in S)/len(S)
    c=lambda S,k:sum(r['cond'][k] is True for r in S)
    P("| %s | %d | %.0f%% / %.0f%% | %d / %d | %d / %d | %d / %d |"%(m,len(x),f(x),f(y),c(x,'I1'),c(y,'I1'),c(x,'K6'),c(y,'K6'),c(x,'P4'),c(y,'P4')))
P("\n外した版の前半の初めの月(2024-08・09)は、前走が見つかる馬が 10%・44% しかなく、前走を使う条件の件数も、2024-08 は 2025 年以降の月の 1 割に満たず、09〜11 月も半分前後にとどまる(K6・P4 の列)。I1 は上のとおり 12 月まで構成上ほぼ 0。**前半に当たる馬の顔ぶれは、前半の後ろの月に偏る**(後半は 2025-10 以降で、ほぼ全月が 85% 以上)。件数が 300 を超えるかどうかは、この偏りを含めた合計で判定している。\n")
P("### 7.3 仮説 1〜8: 前半の |z| ≥ 2 の条件(元の版 11 個 / 外した版 8 個)と、後半\n")
P("検定した条件は元 %d 個・外した版 %d 個(T11 の件数が %d で 300 未満になった)。BH で q < 0.10 かつ |z| ≥ 2 を満たした条件は、**元の版 %d 個 → 外した版 %d 個**。\n"%(len(a['tested']),len(b['tested']),b['main']['T11']['h1']['N'],len(a['passed']),len(b['passed'])))
P("| 条件 | 元の版 前半の読み残し(pt) | z | q | 外した版 前半の件数 | 読み残し(pt) | z | q | 通った | 後半の件数 | 後半の読み残し(pt) | z | 後半の q | 残った |\n|---|---:|---:|---:|---:|---:|---:|---:|:-:|---:|---:|---:|---:|:-:|")
ks=['P4','K6','I1','I4','I9','S3','S4','S5','P8','K1','K3']
for k in ks:
    x=a['main'][k]['h1'];y=b['main'][k]['h1'];h2=b['main'][k].get('h2')
    q=lambda v:'-' if v.get('q_bh') is None else '%.3f'%v['q_bh']
    P("| %s | %+.2f | %+.2f | %s | %d | %+.2f | %+.2f | %s | %s | %s |"%(k,x['res3_pt'],x['z3'],q(x),y['N'],y['res3_pt'],y['z3'],q(y),'○' if y.get('pass') else '×',
       ('%d | %+.2f | %+.2f | %.4f | %s'%(h2['N'],h2['res3_pt'],h2['z3'],h2['q_bh'],'○' if h2['remain'] else '×')) if h2 else '- | - | - | - | -'))
P("\n(P8・K1・K3 は元の版では |z| ≥ 2 だったが、外した版では 2 を下回った。S3〜S5 は前走に依存せず、z は同じ。q が元と違うのは、検定した条件の数が 54 から 53 に変わった BH の違い。)\n")
P("- **通った 3 つ(I1・K6・P4)は、後半でも同じ向きに残った**(I1: -2.81pt・z=-4.91、K6: -2.20pt・z=-3.74、P4: -0.55pt・z=-1.96。q は上の表)。向きは 3 つとも「市場の予測より走らない(買われすぎ)」。**元の版の「1 つも通らなかった」は、外した版では変わる。**")
P("- ただし、通り方は境界に近い。q は I1 0.073・K6 0.030・P4 0.096(基準は 0.10)で、外した版でも 4 番目の I4 が 0.101。P4 は後半の z が -1.96 と小さい(後半の基準は片側の BH で q < 0.10。|z| ≥ 2 は要らない。q は 0.025)。元の版の q(0.144)との差は、条件に当たる馬の入れ替わり(元の版は I1 が前半 2,287 頭、外した版は 2,123 頭)と、前半の初めの月の欠け方の変化の両方から来ている。どちらが効いたかは分けていない。")
P("- 向きが出たのは「休み明け・芝から・前走の大敗」といった前走に依存する条件で、前走が見つからない馬を対象外にしていること自体が、生き残りと逆向きの偏り(前半の初めの月は短い休みの馬だけが前走ありになる)を作りうる。7.2 の I1 の 0 件がその例。**この版が元の版より正しいとまでは言えない**(偏りの種類が変わっただけかもしれない)。\n")
P("### 7.4 2 本目 A(荒れやすいレース)\n")
P("`races.json` は元の版とバイト単位で同じ(レース単位の指標・水準はどれも `horse_runs.csv` を使わない)。**A の 3 水準(R2 の未勝利・馬齢戦・その日の先のレースがない)は変わらない。** 結論も変わらない。\n")
P("### 7.5 2 本目 B(人気薄 20 倍以上)\n")
la=json.load(open(orig+'/ls20.json'));lb=json.load(open(nohr+'/ls20.json'))
P("葉の数は元の版 %d 枚 → 外した版 %d 枚(最大 8 枚)。後半でも残った葉は **元の版 %d 枚 → 外した版 %d 枚**。XGBoost の後半の対数損失(市場だけ → XGBoost)は元の版 %.5f → %.5f、外した版 %.5f → %.5f で、どちらも 0.0003 に届かない差。\n"%(len(la['leaves']),len(lb['leaves']),sum(l['h2']['remain'] for l in la['leaves']),sum(l['h2']['remain'] for l in lb['leaves']),la['xgb_logloss_h2']['market'],la['xgb_logloss_h2']['xgb'],lb['xgb_logloss_h2']['market'],lb['xgb_logloss_h2']['xgb']))
P("| 版 | 葉 | 規則 | 前半 件数 | 前半 読み残し(pt) | z | 後半 件数 | 後半 読み残し(pt) | z | q | 残った |\n|---|---:|---|---:|---:|---:|---:|---:|---:|---:|:-:|")
for nm,L in (('元',la),('外した',lb)):
    for l in L['leaves']:
        h1=l['h1'];h2=l['h2']
        P("| %s | %d | %s | %d | %+.2f | %+.2f | %d | %+.2f | %+.2f | %.3f | %s |"%(nm,l['leaf'],l['rule'],h1['N'],h1['res3_pt'],h1['z3'],h2['N'],h2['res3_pt'],h2['z3'],h2['q_bh'],'○' if h2['remain'] else '×'))
P("\n- 木の形が変わった(元の版の最初の分け目は単勝 43.55 倍のあとに c_K8〈初めての競馬場〉だったのが、外した版では di60〈その日の内有利度〉と prevFinish)。**元の版で残った「展開に泣いた(P1)× 20〜43 倍」と「初めての競馬場 × 前走 12 着以下」の葉は、外した版の木には出ない**。残った 1 枚は「単勝 43.55 倍超 × 前走 6 着以下 × 前走から 28.5 日以内」(-0.50pt、q=0.092)で、極端な人気薄が予測より来ない向き(元の版にもあった式の形のずれ)に近い。")
P("- **B の特徴量に、戦績の記録の長さで意味が変わるものが残っている**(外すかはメインが決める。この節では外していない): ")
P("  - `daysSince`(前走からの日数): 前走が見つからない馬は欠け値になり、記録の始まり(2024-08-10)から遠い月ほど長い休みも見える。**外した版の木が、実際に `daysSince <= 28.5` で分けている**(葉 11・12)。")
P("  - `style`(過去の通過順の平均、3 走以上が要る)と、その他の前走の列(`prevFinish`・`prevPosRatio`・`prevMargin`・`prevLast3fRank`・`prevN`・`prevNinki`・`prevClassDelta`・`distDelta`・`jockeyChanged`): 前走が見つからない馬は欠け値で、欠け値の割合が前半の初めの月ほど高い(7.1・7.2)。")
P("  - 条件の列 `c_*` のうち前走・休み・脚質を使うもの(I・K・P など)も同じ。")
P("  - 外した版の SHAP の上位 15 のうち、`daysSince`・`prevLast3fRank`・`prevFinish`・`prevMargin`・`style` が入っている。\n")
P("### 7.6 この節の結論\n")
P("1. **仮説 1〜8 の結論は変わる**: 元の版は「通る条件なし」、外した版は「I1・K6・P4 が前半で通り、後半でも同じ向きに残った」。ただし 2 回目の判定であり、境界に近く、前走が見つからない馬を除く処理が作る偏りを含む。「次の別の期間で確かめる候補」という位置づけを、「候補の中で I1・K6 が相対的に強い」に更新するのが妥当で、「見落としが見つかった」とまでは書かない。")
P("2. **A は変わらない**(`races.json` 一致)。")
P("3. **B は、後半でも残る葉が 4 枚から 1 枚に減った**。元の版の 4 枚のうち、新しい見落としに近い 2 枚(P1×20〜43倍、初めての競馬場×前走12着以下)は消えた。XGBoost の上積みが小さい(< 0.0003)点は同じで、**学習できる読み残しはほぼ無い**。")
P("4. 元の版の「前半のほうが前走の欠けが多い」という限界は、外した版では 7.2 のとおり前半の初めの月に集中する。")
open(out,'w').write('\n'.join(o)+'\n')
